// the table. The caller is expected to check whether the new index has been
// already provisioned before running any migrations on the table.
func (l *Log) indexExists(tableName string, indexName string) (bool, error) {
	out, err := l.svc.DescribeTable(&dynamodb.DescribeTableInput{
		TableName: aws.String(tableName),
	})
	if err != nil {
		return false, trace.Wrap(convertError(err))
	}
	if out.Table == nil {
		return false, trace.NotFound("table %q not found", tableName)
	}
	for _, index := range out.Table.GlobalSecondaryIndexes {
		if indexNameMatches(aws.StringValue(index.IndexName), indexName) {
			return true, nil
		}
	}
	return false, nil
}

// indexNameMatches compares two global secondary index names. The names of
// the indexes introduced in this package are spelled both as the Go constant
// (indexTimeSearchV2) and as the AWS resource name (timesearchV2), so a
// matching optional "index" prefix is ignored to let callers use either.
func indexNameMatches(existing string, wanted string) bool {
	if existing == wanted {
		return true
	}
	return trimIndexPrefix(strings.ToLower(existing)) == trimIndexPrefix(strings.ToLower(wanted))
}

func trimIndexPrefix(name string) string {
	return strings.TrimPrefix(name, "index")
}

// migrateTimeSearchV2 adds the indexTimeSearchV2 global secondary index to
// the already existing events table and waits until the index becomes active,
// so that the tables created before the index was introduced become
// searchable by day.
func (l *Log) migrateTimeSearchV2(ctx context.Context) error {
	exists, err := l.indexExists(l.Tablename, indexTimeSearchV2)
	if err != nil {
		return trace.Wrap(err)
	}
	if exists {
		return nil
	}

	_, err = l.svc.UpdateTableWithContext(ctx, &dynamodb.UpdateTableInput{
		TableName: aws.String(l.Tablename),
		GlobalSecondaryIndexUpdates: []*dynamodb.GlobalSecondaryIndexUpdate{
			{
				Create: timeSearchV2Index(l.ReadThroughputUnits, l.WriteThroughputUnits),
			},
		},
	})
	if err != nil {
		return trace.Wrap(convertError(err))
	}

	// The index is created in the background, wait until it is ready to be
	// used, otherwise the searches will fail.
	for {
		state, err := l.indexState(ctx, l.Tablename, indexTimeSearchV2)
		if err != nil {
			return trace.Wrap(err)
		}
		if state == dynamodb.IndexStatusActive {
			return nil
		}
		select {
		case <-time.After(dynamoPollPeriod):
		case <-ctx.Done():
			return trace.ConnectionProblem(ctx.Err(), "context canceled")
		}
	}
}

// indexState returns the current status of the given global secondary index,
// e.g. dynamodb.IndexStatusActive or dynamodb.IndexStatusCreating.
func (l *Log) indexState(ctx context.Context, tableName string, indexName string) (string, error) {
	out, err := l.svc.DescribeTableWithContext(ctx, &dynamodb.DescribeTableInput{
		TableName: aws.String(tableName),
	})
	if err != nil {
		return "", trace.Wrap(convertError(err))
	}
	if out.Table == nil {
		return "", trace.NotFound("table %q not found", tableName)
	}
	for _, index := range out.Table.GlobalSecondaryIndexes {
		if indexNameMatches(aws.StringValue(index.IndexName), indexName) {
			return aws.StringValue(index.IndexStatus), nil
		}
	}
	return "", trace.NotFound("index %q not found on table %q", indexName, tableName)
}

