}

func TestScratchDaysBetween(t *testing.T) {
	// Month boundary.
	dates := daysBetween(
		time.Date(2019, 1, 29, 10, 0, 0, 0, time.UTC),
		time.Date(2019, 2, 2, 3, 0, 0, 0, time.UTC))
	require.Equal(t, []string{"2019-01-29", "2019-01-30", "2019-01-31", "2019-02-01", "2019-02-02"}, dates)

	// Same day.
	dates = daysBetween(
		time.Date(2019, 3, 1, 0, 0, 0, 0, time.UTC),
		time.Date(2019, 3, 1, 23, 59, 0, 0, time.UTC))
	require.Equal(t, []string{"2019-03-01"}, dates)

	// Year boundary.
	dates = daysBetween(
		time.Date(2018, 12, 31, 5, 0, 0, 0, time.UTC),
		time.Date(2019, 1, 1, 5, 0, 0, 0, time.UTC))
	require.Equal(t, []string{"2018-12-31", "2019-01-01"}, dates)
}

func TestScratchSearchEvents(t *testing.T) {
	mock := &mockDynamo{t: t}
	l, srv := newMockLog(t, mock)
	defer srv.Close()

	from := time.Date(2019, 1, 30, 0, 0, 0, 0, time.UTC)
	to := time.Date(2019, 2, 1, 12, 0, 0, 0, time.UTC)
	_, err := l.SearchEvents(from, to, "", 0)
	require.NoError(t, err)

	// One query per day (Jan 30, Jan 31, Feb 1).
	require.Len(t, mock.queryCalls, 3)
	for _, in := range mock.queryCalls {
		require.Equal(t, indexTimeSearchV2, aws.StringValue(in.IndexName))
		require.Equal(t, "CreatedAtDate = :date AND CreatedAt BETWEEN :start and :end",
			aws.StringValue(in.KeyConditionExpression))
		require.Len(t, in.ExpressionAttributeValues, 3)
		var strings, numbers int
		for name, v := range in.ExpressionAttributeValues {
			switch name {
			case ":date":
				require.NotNil(t, v.S)
				strings++
			case ":start", ":end":
				require.NotNil(t, v.N)
				numbers++
			default:
				t.Errorf("unexpected placeholder %v", name)
			}
		}
		require.Equal(t, 1, strings)
		require.Equal(t, 2, numbers)
	}
	require.Equal(t, "2019-01-30", aws.StringValue(mock.queryCalls[0].ExpressionAttributeValues[":date"].S))
	require.Equal(t, "2019-02-01", aws.StringValue(mock.queryCalls[2].ExpressionAttributeValues[":date"].S))
}

func TestScratchMigrateDateAttribute(t *testing.T) {
	mock := &mockDynamo{t: t, store: map[string]map[string]*dynamodb.AttributeValue{}}
	l, srv := newMockLog(t, mock)
	defer srv.Close()

	// Seed items without CreatedAtDate (pre-migration format).
	ctx := context.Background()
	for i, ts := range []int64{
		// 2019-01-31T23:00:00Z and 2019-02-01T01:00:00Z
		time.Unix(0, 0).Add(time.Duration(i) * 24 * time.Hour).Unix(),
	} {
		_, err := l.svc.PutItem(&dynamodb.PutItemInput{
			TableName: aws.String("events"),
			Item: map[string]*dynamodb.AttributeValue{
				"SessionID":  {S: aws.String("s1")},
				"EventIndex": {N: aws.String("0")},
				"CreatedAt":  {N: aws.String("1548957600")},
			},
		})
		require.NoError(t, err)
		_ = ts
	}

	require.NoError(t, l.migrateDateAttribute(ctx))
	require.Equal(t, 1, mock.scanCalls)
	for _, item := range mock.store {
		require.Equal(t, "2019-01-31", aws.StringValue(item["CreatedAtDate"].S))
	}

	// Canceled context must abort the migration.
	cctx, cancel := context.WithCancel(context.Background())
	cancel()
	require.Error(t, l.migrateDateAttribute(cctx))
}

